            (room_number, room_type, guest_name, guest_email, guest_cpf,
             check_in, check_out, guests, rate_plan, company_code, status, amount_paid, refund)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
            """;

